import { mkdir, writeFile } from 'node:fs/promises';

const userName = process.env.USER_NAME?.trim() || 'Ivan';
const directory = new URL('../src/environments/', import.meta.url);
await mkdir(directory, { recursive: true });
await writeFile(
  new URL('environment.ts', directory),
  '// Generated by npm run config. Edit USER_NAME in .env, not this file.\n' +
    `export const environment = ${JSON.stringify({ userName }, null, 2)} as const;\n`,
  'utf8',
);
